head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDINF25000";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — page

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "div_93", attr: "__html", fn: function () { return ([String(dma_page.get("total")), String(dma_page.get("currentPage")), String(dma_page.get("pageCount"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("총 <strong id=\"totPage\">" + String(dma_page.get("total")) + "</strong>건 <span id=\"totPage1\">(" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + ")</span>") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_page", fn: function(){ return (!(String(((dma_pageContext.get("page") ?? "")) == null ? '' : ((dma_pageContext.get("page") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_ckKey", fn: function () { return String((dma_pageContext.get("ckKey") ?? "")); } },
        { childId: "ipt_comNm", fn: function () { return String((dma_pageContext.get("comNm") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const pageIndex = "" + dma_page.get("currentPage") + "";
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }
        let temp = $c.util.getComponent('ipt_ckKey').getValue(); if (temp == null) { temp = ''; }
        if (temp === "") {
            $("input[name=ch]").attr("checked", "checked");
        } else {
            /* 수동 전환 필요: 이름 선택자 순회 [name=ch] — B4 반복 밖 동명 입력(정적/계수 틀) · to-be 에 돌 요소가 없다 */ $("input[name=ch]").each(function() {
                    if (temp.match($(this).val())) {
                        $(this).attr("checked", "checked");
                    }
            });
        }
        if ($("input[name=ch]").length === $("input[name=ch]:checked").length) {
            $("input[name=ipt_all]").attr("checked", "checked");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf25000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":0,"mmenu":0
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf25000' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf25000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_openCorpCd_onclick
 * @description btn_openCorpCd 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_openCorpCd_onclick = function(e){
    try {
        scwin.open_corp_cd()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf25000.btn_openCorpCd_onclick' }); }
};

/**
 * @method
 * @name btn_goSearch_onclick
 * @description btn_goSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goSearch_onclick = async function(e){
    try {
        await scwin.goSearch(1)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf25000.btn_goSearch_onclick' }); }
};

/**
 * @method
 * @name btn_fnDownloadChk_onclick
 * @description btn_fnDownloadChk 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnDownloadChk_onclick = async function(e){
    try {
        await scwin.fnDownloadChk()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf25000.btn_fnDownloadChk_onclick' }); }
};

/**
 * @method
 * @name ipt_all_onclick
 * @description ipt_all 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_all_onclick = function(e){
    try {
        scwin.fnCheckAllEvent()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf25000.ipt_all_onclick' }); }
};

/**
 * @method
 * @name ipt_ch01_onclick
 * @description 「m1」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_ch01_onclick = function(e){
    try {
        scwin.fnCheckEvent()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf25000.ipt_ch01_onclick' }); }
};

/**
 * @method
 * @name ipt_ch02_onclick
 * @description 「m2」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_ch02_onclick = function(e){
    try {
        scwin.fnCheckEvent()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf25000.ipt_ch02_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_goSearch
 * @description go Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goSearch = async function () {
    try { return await $c.data.downFile("/down/downList.do?method=searchDownloadIsurList", "", ($c.util.getComponent("dma_goSearchReq") ? $c.util.getComponent("dma_goSearchReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_fnExcelDown
 * @description fn Excel Down 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnExcelDown = async function (action) {
    try { return await $c.data.downFile(action ?? "/down/excel.do?method=searchDownloadIsurExcel", "", ($c.util.getComponent("dma_fnExcelDownReq") ? $c.util.getComponent("dma_fnExcelDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnCheckAllEvent
 * @description fn Check All Event 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckAllEvent = function () {
    const form = $("form[name=JLDINF25000]");
    const allChk = $("input[name=ipt_all]").is(":checked");
    if (allChk) {
        $("input[name=ch]", form).attr("checked", "checked");
    } else {
        $("input[name=ch]", form).removeAttr("checked");
    }
};

/**
 * @method
 * @name fnCheckEvent
 * @description fn Check Event 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckEvent = function () {
    const form = $("form[name=JLDINF25000]");
    const len = $("input[name=ch]:checked").length;
    if (len === 2) {
        $("input[name=ipt_all]", form).attr("checked", "checked");
    } else {
        $("input[name=ipt_all]", form).removeAttr("checked");
    }
};

/**
 * @method
 * @name open_corp_cd
 * @description open corp cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.open_corp_cd = function () {
    formName = (document.JLDINF25000 || { elements: [] });
    fn_popupCorpSearch(formName);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_popupCorpSearch — JSP 팝업(window.open+폼 제출 — 회신)
};

/**
 * @method
 * @name goSearch
 * @description go Search 처리
 * @param {Number} idx idx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goSearch = async function (idx) {
    const items = $("input[name=ch]:checked").map(function() {
            return $(this).val();
    }).get();
    $c.util.getComponent('ipt_ckKey').setValue(items);
    if (idx === '1') {
        $c.util.getComponent('ipt_pageIndex').setValue("1");
    }
    await scwin.tx_goSearch();
};

/**
 * @method
 * @name fnDownloadChk
 * @description fn Download Chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownloadChk = async function () {
    const form = (document.JLDINF25000 || { elements: [] });
    fn_downInfoWin(form);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_downInfoWin — JSP 팝업(window.open+폼 제출 — 회신)
    await $c.win.alert("조회 내용이 없습니다.");
};

/**
 * @method
 * @name fnExcelDown
 * @description fn Excel Down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnExcelDown = async function () {
    const items = $("input[name=ch]:checked").map(function() {
            return $(this).val();
    }).get();
    $c.util.getComponent('ipt_ckKey').setValue(items);
    fm = (document.JLDINF25000 || { elements: [] });
    fm.method = 'post';
    await scwin.tx_fnExcelDown('/down/excel.do?method=searchDownloadIsurExcel');
};

/**
 * @method
 * @name krxpage_pagenavigator_102_onclick
 * @description krxpage_pagenavigator_102 클릭 이벤트
 * @param {Number} index index
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.krxpage_pagenavigator_102_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        await scwin.goSearch(index);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldinf25000.krxpage_pagenavigator_102_onclick" });
    }
};
